+// Test fixture for Triangle tests
+class TriangleTest : public ::testing::Test {
+protected:
+    // Helper to check if two doubles are approximately equal
+    void ExpectNear(double expected, double actual, double tolerance = 1e-9) {
+        EXPECT_NEAR(expected, actual, tolerance);
+    }
+};
+
+// 1. Test successful parsing and area calculation for a valid triangle (3, 4, 5)
+TEST_F(TriangleTest, ValidTriangleArea) {
+    // 3, 4, 5 is a right triangle, area = 0.5 * 3 * 4 = 6.0
+    // Using Heron's formula: s = (3+4+5)/2 = 6. Area = sqrt(6*(6-3)*(6-4)*(6-5)) = sqrt(6*3*2*1) = sqrt(36) = 6.0
+    try {
+        Triangle t(3.0, 4.0, 5.0);
+        ExpectNear(6.0, t.area());
+    } catch (const std::invalid_argument& e) {
+        FAIL() << "Valid triangle construction threw an exception: " << e.what();
+    }
+}
+
+// Test another valid triangle (e.g., equilateral triangle with side 2)
+TEST_F(TriangleTest, EquilateralTriangleArea) {
+    // Side = 2. Area = (sqrt(3)/4) * side^2 = (sqrt(3)/4) * 4 = sqrt(3)
+    try {
+        Triangle t(2.0, 2.0, 2.0);
+        double expected_area = std::sqrt(3.0);
+        ExpectNear(expected_area, t.area());
+    } catch (const std::invalid_argument& e) {
+        FAIL() << "Equilateral triangle construction threw an exception: " << e.what();
+    }
+}
+
+
+// 2. Test constructor throws std::invalid_argument for non-positive side length
