+    }, std::invalid_argument);
+
+    // Test negative side
+    EXPECT_THROW({
+        Triangle t(3.0, -4.0, 5.0);
+    }, std::invalid_argument);
+}
+
+// 3. Test constructor throws std::invalid_argument for impossible triangle (Triangle Inequality Theorem violation)
+TEST_F(TriangleTest, ImpossibleTriangleThrows) {
+    // 1 + 2 <= 10 (False, but 1+2 < 10)
+    EXPECT_THROW({
+        Triangle t(1.0, 2.0, 10.0);
+    }, std::invalid_argument);
